import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function CreerClasse() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    nom: "",
    niveau: "",
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Vérification frontend
    if (!formData.nom.trim() || !formData.niveau.trim()) {
      alert("❌ Nom et niveau sont obligatoires");
      return;
    }

    setLoading(true);

    try {
      const token = localStorage.getItem("token");

      const response = await fetch("http://localhost:5000/api/classes/create", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          nom: formData.nom.trim(),
          niveau: formData.niveau.trim(),
        }),
      });

      const result = await response.json();

      if (response.ok && result.success) {
        alert("✅ Classe créée avec succès !");
        setFormData({ nom: "", niveau: "" });
        navigate("/creer-cours"); // rediriger vers créer cours si bghiti
      } else {
        alert(`❌ Erreur: ${result.message || "Erreur lors de la création"}`);
      }
    } catch (error) {
      console.error(error);
      alert("❌ Erreur serveur");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mt-5">
      <h2 className="mb-4 text-center">🏫 Créer une Classe</h2>
      <form onSubmit={handleSubmit} className="p-4 border rounded shadow-sm bg-light">
        {/* Nom */}
        <div className="mb-3">
          <label className="form-label">Nom de la classe :</label>
          <input
            type="text"
            name="nom"
            value={formData.nom}
            onChange={handleChange}
            className="form-control"
            placeholder="Ex: 1ère année"
            required
          />
        </div>

        {/* Niveau */}
        <div className="mb-3">
          <label className="form-label">Niveau :</label>
          <input
            type="text"
            name="niveau"
            value={formData.niveau}
            onChange={handleChange}
            className="form-control"
            placeholder="Ex: Licence"
            required
          />
        </div>

        <button type="submit" className="btn btn-primary w-100" disabled={loading}>
          {loading ? "Création en cours..." : "Créer la Classe"}
        </button>
      </form>
    </div>
  );
}

export default CreerClasse;
